mapper.sql:
WITH BASIC AS ( SELECT CHRT.ORG_ID , ORG.ORGNM , CHRT.DGRS_YR , CHRT.DGRS_SMSTR_CHRT , CHRT.SMSTR_CHRTNM , SBJCT.SBJCT_ID , SBJCT.CRCLMN_NO , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , SBJCT.MRK_PROC_SDTTM , SBJCT.MRK_PROC_EDTTM , SBJCT_ADM.PROF_USER_ID , SBJCT_ADM.PROF_USERNM , SBJCT_ADM.TUT_USER_ID , SBJCT_ADM.TUT_USERNM FROM TB_LMS_SBJCT SBJCT JOIN TB_LMS_SMSTR_CHRT CHRT ON CHRT.SMSTR_CHRT_ID = SBJCT.SMSTR_CHRT_ID LEFT JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = CHRT.ORG_ID LEFT JOIN ( SELECT ADM.SBJCT_ID , MAX(CASE WHEN ADM.SBJCT_ADM_TYCD = 'PROF' THEN USR.USER_ID END) AS PROF_USER_ID , MAX(CASE WHEN ADM.SBJCT_ADM_TYCD = 'PROF' THEN USR.USERNM END) AS PROF_USERNM , MAX(CASE WHEN ADM.SBJCT_ADM_TYCD = 'TUT' THEN USR.USER_ID END) AS TUT_USER_ID , MAX(CASE WHEN ADM.SBJCT_ADM_TYCD = 'TUT' THEN USR.USERNM END) AS TUT_USERNM FROM TB_LMS_SBJCT_ADM ADM JOIN TB_LMS_USER USR ON USR.USER_ID = ADM.USER_ID GROUP BY ADM.SBJCT_ID ) SBJCT_ADM ON SBJCT_ADM.SBJCT_ID = SBJCT.SBJCT_ID WHERE SBJCT.DELYN = 'N'
AND CHRT.ORG_ID = #{orgId}
AND CHRT.SMSTR_CHRT_ID = #{smstrChrtId}
AND ( LOWER(TO_CHAR(SBJCT.CRCLMN_NO)) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(SBJCT.SBJCTNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(SBJCT_ADM.PROF_USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
), MRK AS ( /* 최종확정/평가취소는 점수환산상태코드(SCR_CNVS_STSCD) 공통코드로 판단한다. */ SELECT SBJCT_ID , MAX(CASE WHEN SCR_CNVS_STSCD = 'MRK_CNVS_CMPTN' THEN 1 ELSE 0 END) AS FINAL_YN , MAX(CASE WHEN SCR_CNVS_STSCD = 'MRK_CNVS_CNCL' THEN 1 ELSE 0 END) AS CANCEL_YN FROM TB_LMS_SBJCT_MRK GROUP BY SBJCT_ID ), STATUS AS ( SELECT B.* /* 평가취소/최종확정은 상태코드 우선, 산출전/산출중은 성적처리기간 기준으로 산정한다. */ , CASE WHEN NVL(M.CANCEL_YN, 0) = 1 THEN 'CANCEL' WHEN NVL(M.FINAL_YN, 0) = 1 THEN 'FINAL' WHEN B.MRK_PROC_SDTTM IS NOT NULL AND FN_DTTM() < B.MRK_PROC_SDTTM THEN 'BEFORE' WHEN B.MRK_PROC_SDTTM IS NOT NULL AND B.MRK_PROC_EDTTM IS NOT NULL AND FN_DTTM() BETWEEN B.MRK_PROC_SDTTM AND B.MRK_PROC_EDTTM THEN 'ING' ELSE 'NONE' END AS MRK_PROC_STATUS_CD /* 성적 재산정 예외기간에 현재 시각이 포함되면 기간예외 Y로 표시한다. */ , CASE WHEN EXISTS ( SELECT 1 FROM TB_LMS_MRK_PROC_EXCP_PROC EXCP WHERE EXCP.SBJCT_ID = B.SBJCT_ID AND EXCP.PROC_SDTTM IS NOT NULL AND EXCP.PROC_EDTTM IS NOT NULL AND FN_DTTM() BETWEEN EXCP.PROC_SDTTM AND EXCP.PROC_EDTTM ) THEN 'Y' ELSE 'N' END AS PRD_EXCP_YN FROM BASIC B LEFT JOIN MRK M ON M.SBJCT_ID = B.SBJCT_ID ) SELECT A.* FROM STATUS A WHERE 1 = 1
AND ( (INSTR(',' || #{mrkProcStatusCds} || ',', ',BEFORE,') > 0 AND A.MRK_PROC_STATUS_CD = 'BEFORE') OR (INSTR(',' || #{mrkProcStatusCds} || ',', ',ING,') > 0 AND A.MRK_PROC_STATUS_CD = 'ING') OR (INSTR(',' || #{mrkProcStatusCds} || ',', ',FINAL,') > 0 AND A.MRK_PROC_STATUS_CD = 'FINAL') OR (INSTR(',' || #{mrkProcStatusCds} || ',', ',CANCEL,') > 0 AND A.MRK_PROC_STATUS_CD = 'CANCEL') )

WITH HSTRY AS ( /* 원본 로그 + RN */ SELECT H.* , ROW_NUMBER() OVER( PARTITION BY H.SBJCT_ID, H.USER_ID, H.REG_DTTM, H.MRK_PROC_HSTRY_TYCD ORDER BY H.MRK_PROC_HSTRY_ID DESC ) AS TY_RN FROM TB_LMS_MRK_PROC_HSTRY H WHERE H.SBJCT_ID = #{sbjctId}
AND H.ORG_ID = #{orgId}
), PROC_BASE AS ( /* 학생 + 처리일시 묶음 */ SELECT H.SBJCT_ID , H.ORG_ID , H.USER_ID , H.STDNT_NO , H.REG_DTTM , MAX(H.RGTR_ID) KEEP (DENSE_RANK LAST ORDER BY H.MRK_PROC_HSTRY_ID) AS RGTR_ID FROM HSTRY H WHERE H.TY_RN = 1 GROUP BY H.SBJCT_ID , H.ORG_ID , H.USER_ID , H.STDNT_NO , H.REG_DTTM ), PROC_FILTERED AS ( /* LINE_NO 작업 */ SELECT ROW_NUMBER() OVER(ORDER BY PB.REG_DTTM DESC, USR.USERNM, PB.STDNT_NO, PB.USER_ID) AS LINE_NO , PB.SBJCT_ID , PB.ORG_ID , PB.USER_ID , PB.STDNT_NO , USR.USERNM , PB.REG_DTTM , PB.RGTR_ID , RGTR.USERNM AS RGTRNM FROM PROC_BASE PB LEFT JOIN TB_LMS_USER USR ON USR.USER_ID = PB.USER_ID LEFT JOIN TB_LMS_USER RGTR ON RGTR.USER_ID = PB.RGTR_ID WHERE 1 = 1
AND ( LOWER(USR.USER_ID) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(USR.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(PB.STDNT_NO) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
) /* 페이징된 묶음에 다시 점수유형별 점수를 붙이기 */ SELECT PU.LINE_NO , PU.USER_ID , PU.STDNT_NO , PU.USERNM , PU.REG_DTTM , PU.RGTR_ID , PU.RGTRNM , LH.MRK_PROC_HSTRY_TYCD , LH.SCR_BFR , LH.SCR_AFT FROM PROC_FILTERED PU LEFT JOIN HSTRY LH ON LH.SBJCT_ID = PU.SBJCT_ID AND LH.USER_ID = PU.USER_ID AND LH.REG_DTTM = PU.REG_DTTM AND LH.TY_RN = 1 WHERE 1 = 1

mapper.insert:
/*
    SQL ID : MrkProcStatusDAO.listMrkProcStatus
    내용 : 성적처리현황 일괄 등록
*/

    INSERT INTO TB_LMS_MRK_PROC_HSTRY
    (
          MRK_PROC_HSTRY_ID
        , ORG_ID
        , DEPT_ID
        , DGRS_YR
        , DGRS_SMSTR_CHRT
        , SBJCT_ID
        , STDNT_NO
        , USER_ID
        , MRK_PROC_HSTRY_TYCD
        , SCR_BFR
        , SCR_AFT
        , RGTR_ID
        , REG_DTTM
    )
    SELECT
          #{item.mrkProcHstryId}
        , #{item.orgId}
        , #{item.deptId, jdbcType=VARCHAR}
        , #{item.dgrsYr}
        , #{item.dgrsSmstrChrt}
        , #{item.sbjctId}
        , U.STDNT_NO
        , #{item.userId}
        , #{item.mrkProcHstryTycd}
        , #{item.scrBfr}
        , #{item.scrAft}
        , #{item.rgtrId}
        , FN_DTTM()
    FROM TB_LMS_USER U
    WHERE U.USER_ID = #{item.userId}
